package com.fieldkit.deviceinfo

import android.content.Context
import android.os.BatteryManager
import android.os.Build
import com.facebook.react.bridge.ReactApplicationContext

// NativeDeviceInfoSpec is generated by Codegen from src/NativeDeviceInfo.ts
// (build/generated/source/codegen/java/com/fieldkit/deviceinfo/NativeDeviceInfoSpec.java).
// Each spec method becomes an abstract method here; a missing override is a compile error.
class NativeDeviceInfoModule(reactContext: ReactApplicationContext) :
  NativeDeviceInfoSpec(reactContext) {

  override fun getName() = NAME

  override fun getBatteryLevel(): Double {
    val manager = reactApplicationContext.getSystemService(Context.BATTERY_SERVICE) as? BatteryManager
      ?: return -1.0
    // Integer.MIN_VALUE when the device doesn't report capacity
    val percent = manager.getIntProperty(BatteryManager.BATTERY_PROPERTY_CAPACITY)
    return if (percent in 0..100) percent / 100.0 else -1.0
  }

  override fun getModel(): String = "${Build.MANUFACTURER} ${Build.MODEL}"

  // Heuristic: there is no official API. Covers the stock Android Studio emulator images.
  override fun isEmulator(): Boolean =
    Build.FINGERPRINT.startsWith("generic") ||
      Build.FINGERPRINT.contains("emulator") ||
      Build.HARDWARE.contains("ranchu") ||
      Build.HARDWARE.contains("goldfish") ||
      Build.MODEL.contains("sdk_gphone") ||
      Build.PRODUCT.contains("sdk")

  companion object {
    const val NAME = "NativeDeviceInfo"
  }
}
